  3→using Avalonia;
  4→using Avalonia.Controls;
  5→using Avalonia.Controls.Documents;
  6→using Avalonia.Media;
  7→
  8→namespace DemoApp.CollaborativeEditor.Controls;
  9→
 10→using TextEditFormattedText = Six.Automerge.TextEdit.FormattedText;
 11→
 12→public partial class RichTextEditor : UserControl
 13→{
 14→  public static readonly StyledProperty<string> TextProperty =
 15→    AvaloniaProperty.Register<RichTextEditor, string>(nameof(Text), defaultValue: string.Empty);
 16→
 17→  public static readonly StyledProperty<TextEditFormattedText?> FormattedTextProperty =
 18→    AvaloniaProperty.Register<RichTextEditor, TextEditFormattedText?>(nameof(FormattedText));
 19→
 20→  public static readonly StyledProperty<int> CaretIndexProperty =
 21→    AvaloniaProperty.Register<RichTextEditor, int>(nameof(CaretIndex));
 22→
 23→  public static readonly StyledProperty<int> SelectionStartProperty =
 24→    AvaloniaProperty.Register<RichTextEditor, int>(nameof(SelectionStart));
 25→
 26→  public static readonly StyledProperty<int> SelectionEndProperty =
 27→    AvaloniaProperty.Register<RichTextEditor, int>(nameof(SelectionEnd));
 28→
 29→  bool _isSyncingText;
 30→
 31→  public RichTextEditor()
 32→  {
 33→    InitializeComponent();
 34→    WireInputTextBox();
 35→  }
 36→
 37→  public string Text
 38→  {
 39→    get => GetValue(TextProperty);
 40→    set => SetValue(TextProperty, value);
 41→  }
 42→
 43→  public TextEditFormattedText? FormattedText
 44→  {
 45→    get => GetValue(FormattedTextProperty);
 46→    set => SetValue(FormattedTextProperty, value);
 47→  }
 48→
 49→  public int CaretIndex
 50→  {
 51→    get => GetValue(CaretIndexProperty);
 52→    set => SetValue(CaretIndexProperty, value);
 53→  }
 54→
 55→  public int SelectionStart
 56→  {
 57→    get => GetValue(SelectionStartProperty);
 58→    set => SetValue(SelectionStartProperty, value);
 59→  }
 60→
 61→  public int SelectionEnd
 62→  {
 63→    get => GetValue(SelectionEndProperty);
 64→    set => SetValue(SelectionEndProperty, value);
 65→  }
 66→
 67→  /// <summary>
 68→  /// Gets whether the internal text input has keyboard focus.
 69→  /// </summary>
 70→  public bool IsEditorFocused => InputTextBox.IsFocused;
 71→
 72→  protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
 73→  {
 74→    base.OnPropertyChanged(change);
 75→
 76→    if(change.Property == TextProperty)
 77→    {
 78→      SyncTextToInputTextBox();
 79→    }
 80→    else if(change.Property == FormattedTextProperty)
 81→    {
 82→      RenderFormattedText();
 83→    }
 84→  }
 85→
 86→  void WireInputTextBox()
 87→  {
 88→    InputTextBox.PropertyChanged += (_, args) =>
 89→    {
 90→      if(args.Property == TextBox.TextProperty && !_isSyncingText)
 91→      {
 92→        _isSyncingText = true;
 93→        try
 94→        {
 95→          Text = InputTextBox.Text ?? string.Empty;
 96→        }
 97→        finally
 98→        {
 99→          _isSyncingText = false;
100→        }
101→      }
102→      else if(args.Property == TextBox.CaretIndexProperty)
103→      {
104→        CaretIndex = InputTextBox.CaretIndex;
105→      }
106→      else if(args.Property == TextBox.SelectionStartProperty)
107→      {
108→        SelectionStart = InputTextBox.SelectionStart;
109→      }
110→      else if(args.Property == TextBox.SelectionEndProperty)
111→      {
112→        SelectionEnd = InputTextBox.SelectionEnd;
113→      }
114→    };
115→  }
116→
117→  void SyncTextToInputTextBox()
118→  {
119→    if(_isSyncingText)
120→    {
121→      return;
122→    }
123→
124→    _isSyncingText = true;
125→    try
126→    {
127→      string newText = Text ?? string.Empty;
128→      if(InputTextBox.Text != newText)
129→      {
130→        int caretBefore = InputTextBox.CaretIndex;
131→        InputTextBox.Text = newText;
132→
133→        // Restore caret position, clamped to text length
134→        InputTextBox.CaretIndex = Math.Min(caretBefore, newText.Length);
135→      }
136→    }
137→    finally
138→    {
139→      _isSyncingText = false;
140→    }
141→  }
142→
143→  void RenderFormattedText()
144→  {
145→    TextEditFormattedText? formatted = FormattedText;
146→    Console.Error.WriteLine($"[RichTextEditor] RenderFormattedText called, formatted={formatted is not null}, spans={formatted?.Spans.Count ?? 0}");
147→    if(formatted is null)
148→    {
149→      DisplayTextBlock.Inlines?.Clear();
150→      return;
151→    }
152→
153→    FormattedTextRenderer.Render(DisplayTextBlock, formatted);
154→    Console.Error.WriteLine($"[RichTextEditor] After render, inlines count={DisplayTextBlock.Inlines?.Count ?? 0}");
155→  }
156→}
