  3→using System.Reactive;
  4→using Avalonia.Controls;
  5→using Avalonia.Input;
  6→using Avalonia.Threading;
  7→using DemoApp.CollaborativeEditor.Controls;
  8→using DemoApp.CollaborativeEditor.ViewModels;
  9→using DemoApp.Shared;
 10→using DemoApp.Shared.Controls;
 11→using Microsoft.Extensions.DependencyInjection;
 12→using Microsoft.Extensions.Logging;
 13→using Microsoft.Extensions.Logging.Abstractions;
 14→using ReactiveUI;
 15→using Six.Automerge.TextEdit;
 16→
 17→namespace DemoApp.CollaborativeEditor.Views;
 18→
 19→public partial class EditorWindow : Window
 20→{
 21→  readonly ILogger<EditorWindow> _logger;
 22→  DocumentSessionDialogViewModel? _sessionVm;
 23→  ConnectionStatusBarViewModel? _statusBarVm;
 24→
 25→  public EditorWindow()
 26→  {
 27→    var loggerFactory = App.Services?.GetService<ILoggerFactory>();
 28→    _logger = (loggerFactory ?? NullLoggerFactory.Instance).CreateLogger<EditorWindow>();
 29→    InitializeComponent();
 30→    Loaded += OnLoaded;
 31→  }
 32→
 33→  async void OnLoaded(object? sender, EventArgs e)
 34→  {
 35→    _sessionVm = new DocumentSessionDialogViewModel();
 36→    _sessionVm.ResultReady += OnSessionResultReady;
 37→
 38→    SessionDialog.DataContext = _sessionVm;
 39→    SessionDialog.RefreshRequested += OnRefreshRequested;
 40→
 41→    _statusBarVm = new ConnectionStatusBarViewModel();
 42→    StatusBar.DataContext = _statusBarVm;
 43→
 44→    // Track caret position and selection changes from the RichTextEditor
 45→    LocalEditor.PropertyChanged += (_, args) =>
 46→    {
 47→      if(DataContext is not EditorViewModel vm)
 48→      {
 49→        return;
 50→      }
 51→
 52→      if(args.Property == RichTextEditor.CaretIndexProperty)
 53→      {
 54→        vm.CursorPosition = LocalEditor.CaretIndex;
 55→      }
 56→
 57→      if(args.Property == RichTextEditor.SelectionStartProperty || args.Property == RichTextEditor.SelectionEndProperty)
 58→      {
 59→        int start = LocalEditor.SelectionStart;
 60→        int end = LocalEditor.SelectionEnd;
 61→        int newLength = Math.Abs(end - start);
 62→
 63→        // Only clear selection length when the TextBox actually has focus.
 64→        // This preserves the last known selection when toolbar buttons steal focus.
 65→        if(newLength > 0 || LocalEditor.IsEditorFocused)
 66→        {
 67→          vm.SelectionLength = newLength;
 68→        }
 69→      }
 70→    };
 71→
 72→    // Handle formatting button clicks in code-behind to preserve selection state
 73→    BoldButton.Click += (_, _) => ExecuteFormatCommand(vm => vm.ToggleBoldCommand);
 74→    ItalicButton.Click += (_, _) => ExecuteFormatCommand(vm => vm.ToggleItalicCommand);
 75→    UnderlineButton.Click += (_, _) => ExecuteFormatCommand(vm => vm.ToggleUnderlineCommand);
 76→
 77→    // Handle Ctrl+B/I/U keyboard shortcuts via tunnel routing (before TextBox consumes them)
 78→    LocalEditor.AddHandler(KeyDownEvent, OnEditorKeyDown, Avalonia.Interactivity.RoutingStrategies.Tunnel);
 79→
 80→    // Load stored documents, initialize connection, then fetch server documents
 81→    if(DataContext is EditorViewModel vm2 && vm2.RepoService is not null)
 82→    {
 83→      _sessionVm.LoadStoredDocuments(vm2.RepoService.StorageDirectory);
 84→      await vm2.RepoService.InitializeAsync();
 85→      WireConnectionEvents(vm2.RepoService);
 86→      await _sessionVm.LoadServerDocumentsAsync(vm2.RepoService);
 87→    }
 88→  }
 89→
 90→  async void OnRefreshRequested(object? sender, EventArgs e)
 91→  {
 92→    if(_sessionVm is null || DataContext is not EditorViewModel vm || vm.RepoService is null)
 93→    {
 94→      return;
 95→    }
 96→
 97→    await _sessionVm.LoadServerDocumentsAsync(vm.RepoService);
 98→  }
 99→
100→  async void OnSessionResultReady(object? sender, EventArgs e)
101→  {
102→    if(_sessionVm?.Result is null || DataContext is not EditorViewModel vm)
103→    {
104→      return;
105→    }
106→
107→    var result = _sessionVm.Result;
108→    _sessionVm.IsLoading = true;
109→    _sessionVm.ErrorMessage = null;
110→
111→    try
112→    {
113→      switch(result.Action)
114→      {
115→        case SessionAction.Create:
116→          await HandleCreateAsync(vm);
117→          break;
118→        case SessionAction.Join:
119→          await HandleJoinAsync(vm, result.DocumentId!);
120→          break;
121→        case SessionAction.Resume:
122→          await HandleResumeAsync(vm, result.DocumentId!);
123→          break;
124→      }
125→
126→      await Dispatcher.UIThread.InvokeAsync(() => _sessionVm.IsLoading = false);
127→    }
128→    catch(OperationCanceledException ex)
129→    {
130→      _logger.LogWarning(ex, "Document {Action} was cancelled", result.Action);
131→      await Dispatcher.UIThread.InvokeAsync(() =>
132→      {
133→        vm.SyncStatus = "Operation cancelled";
134→        _sessionVm.IsLoading = false;
135→      });
136→    }
137→    catch(TimeoutException ex)
138→    {
139→      _logger.LogWarning(ex, "Document {Action} timed out", result.Action);
140→      await Dispatcher.UIThread.InvokeAsync(() =>
141→      {
142→        vm.SyncStatus = "Operation timed out";
143→        _sessionVm.ErrorMessage = "The operation timed out. The document may be unavailable or the server is not responding.";
144→        _sessionVm.IsLoading = false;
145→      });
146→    }
147→    catch(Exception ex)
148→    {
149→      _logger.LogWarning(ex, "Document {Action} failed", result.Action);
150→      await Dispatcher.UIThread.InvokeAsync(() =>
151→      {
152→        vm.SyncStatus = $"Error: {ex.Message}";
153→        _sessionVm.ErrorMessage = ex.Message;
154→        _sessionVm.IsLoading = false;
155→      });
156→    }
157→  }
158→
159→  async Task HandleCreateAsync(EditorViewModel vm)
160→  {
161→    if(vm.RepoService is null)
162→    {
163→      _logger.LogInformation("Creating offline document (no RepoService)");
164→      await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Creating...");
165→
166→      // For offline mode, create a standalone repo with in-memory adapters
167→      var repo = new Six.Automerge.Repository.Repo(new Six.Automerge.Repository.RepoConfig());
168→      TextDocument textDoc = await TextDocument.CreateAsync(repo);
169→
170→      await Dispatcher.UIThread.InvokeAsync(() =>
171→      {
172→        vm.SetTextDocument(textDoc);
173→        vm.SyncStatus = "Ready (offline)";
174→      });
175→      await ShowEditorAsync(null);
176→      return;
177→    }
178→
179→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Creating...");
180→    await vm.RepoService.InitializeAsync();
181→    WireConnectionEvents(vm.RepoService);
182→
183→    TextDocument textDocument = await TextDocument.CreateAsync(vm.RepoService.Repo!);
184→
185→    await Dispatcher.UIThread.InvokeAsync(() =>
186→    {
187→      vm.SetTextDocument(textDocument);
188→      vm.SyncStatus = "Ready";
189→    });
190→
191→    _logger.LogInformation("Created document {DocumentId}", textDocument.DocumentId);
192→    await ShowEditorAsync(textDocument.DocumentId);
193→  }
194→
195→  async Task HandleJoinAsync(EditorViewModel vm, string documentId)
196→  {
197→    if(vm.RepoService is null)
198→    {
199→      _logger.LogWarning("Cannot join document {DocumentId}: no server connection", documentId);
200→      await Dispatcher.UIThread.InvokeAsync(() =>
201→        _sessionVm!.ErrorMessage = "Cannot join: no server connection");
202→      return;
203→    }
204→
205→    await vm.RepoService.InitializeAsync();
206→    WireConnectionEvents(vm.RepoService);
207→
208→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Joining...");
209→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Syncing...");
210→
211→    TextDocument? textDocument = await TextDocument.OpenAsync(
212→      vm.RepoService.Repo!,
213→      documentId,
214→      timeout: TimeSpan.FromSeconds(30));
215→
216→    if(textDocument is null)
217→    {
218→      _logger.LogWarning("Join failed: document {DocumentId} not found", documentId);
219→      await Dispatcher.UIThread.InvokeAsync(() =>
220→      {
221→        _sessionVm!.ErrorMessage = "Document not found";
222→        vm.SyncStatus = "Disconnected";
223→      });
224→      return;
225→    }
226→
227→    await Dispatcher.UIThread.InvokeAsync(() =>
228→    {
229→      vm.SetTextDocument(textDocument);
230→      vm.SyncStatus = "Ready";
231→    });
232→
233→    _logger.LogInformation("Joined document {DocumentId}", textDocument.DocumentId);
234→    await ShowEditorAsync(textDocument.DocumentId);
235→  }
236→
237→  async Task HandleResumeAsync(EditorViewModel vm, string documentId)
238→  {
239→    if(vm.RepoService is null)
240→    {
241→      _logger.LogWarning("Cannot resume document {DocumentId}: no server connection", documentId);
242→      await Dispatcher.UIThread.InvokeAsync(() =>
243→        _sessionVm!.ErrorMessage = "Cannot resume: no server connection");
244→      return;
245→    }
246→
247→    await vm.RepoService.InitializeAsync();
248→    WireConnectionEvents(vm.RepoService);
249→
250→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Resuming...");
251→
252→    TextDocument? textDocument = await TextDocument.OpenAsync(
253→      vm.RepoService.Repo!,
254→      documentId,
255→      timeout: TimeSpan.FromSeconds(10));
256→
257→    if(textDocument is null)
258→    {
259→      _logger.LogWarning("Resume failed: document {DocumentId} not found in storage", documentId);
260→      await Dispatcher.UIThread.InvokeAsync(() =>
261→      {
262→        _sessionVm!.ErrorMessage = "Document not found in storage";
263→        vm.SyncStatus = "Disconnected";
264→      });
265→      return;
266→    }
267→
268→    await Dispatcher.UIThread.InvokeAsync(() =>
269→    {
270→      vm.SetTextDocument(textDocument);
271→      vm.SyncStatus = "Ready";
272→    });
273→
274→    _logger.LogInformation("Resumed document {DocumentId}", textDocument.DocumentId);
275→    await ShowEditorAsync(textDocument.DocumentId);
276→  }
277→
278→  void WireConnectionEvents(RepoService repoService)
279→  {
280→    if(_statusBarVm is null)
281→    {
282→      return;
283→    }
284→
285→    _statusBarVm.PeerId = repoService.PeerId?.ToString();
286→    _statusBarVm.ServerUrl = repoService is { IsInitialized: true }
287→      ? "Connected"
288→      : "Offline";
289→
290→    // Set initial connection state (event handler below only fires on future changes)
291→    DemoApp.Shared.ConnectionState MapState(ConnectionState s) => s switch
292→    {
293→      ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
294→      ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
295→      ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
296→      _ => DemoApp.Shared.ConnectionState.Disconnected
297→    };
298→
299→    _statusBarVm.ConnectionState = MapState(repoService.ConnectionState);
300→
301→    repoService.ConnectionStateChanged += (_, state) =>
302→      Dispatcher.UIThread.Post(() =>
303→      {
304→        if(_statusBarVm is not null)
305→        {
306→          _statusBarVm.ConnectionState = MapState(state);
307→        }
308→
309→        if(DataContext is EditorViewModel vm && vm.TextDocument is not null)
310→        {
311→          vm.UpdateConnectionStatus(MapState(state), repoService.PeerCount);
312→        }
313→      });
314→
315→    repoService.PeerCountChanged += (_, count) =>
316→      Dispatcher.UIThread.Post(() =>
317→      {
318→        if(_statusBarVm is not null)
319→        {
320→          _statusBarVm.PeerCount = count;
321→        }
322→
323→        if(DataContext is EditorViewModel vm && vm.TextDocument is not null)
324→        {
325→          vm.UpdateConnectionStatus(MapState(repoService.ConnectionState), count);
326→        }
327→      });
328→  }
329→
330→  async Task ShowEditorAsync(string? documentId)
331→  {
332→    await Dispatcher.UIThread.InvokeAsync(() =>
333→    {
334→      SessionPanel.IsVisible = false;
335→      EditorPanel.IsVisible = true;
336→
337→      if(_statusBarVm is not null)
338→      {
339→        _statusBarVm.DocumentId = documentId ?? "local";
340→      }
341→
342→      LocalEditor.Focus();
343→    });
344→  }
345→
346→  void OnEditorKeyDown(object? sender, KeyEventArgs e)
347→  {
348→    if(e.KeyModifiers != KeyModifiers.Control)
349→    {
350→      return;
351→    }
352→
353→    Func<EditorViewModel, ReactiveCommand<Unit, Unit>>? commandSelector = e.Key switch
354→    {
355→      Key.B => vm => vm.ToggleBoldCommand,
356→      Key.I => vm => vm.ToggleItalicCommand,
357→      Key.U => vm => vm.ToggleUnderlineCommand,
358→      _ => null
359→    };
360→
361→    if(commandSelector is not null)
362→    {
363→      ExecuteFormatCommand(commandSelector);
364→      e.Handled = true;
365→    }
366→  }
367→
368→  void ExecuteFormatCommand(Func<EditorViewModel, ReactiveCommand<Unit, Unit>> commandSelector)
369→  {
370→    if(DataContext is not EditorViewModel vm)
371→    {
372→      return;
373→    }
374→
375→    commandSelector(vm).Execute().Subscribe();
376→  }
377→}
