 7→/// <summary>
 8→/// Tracks which formatting marks are active at the current cursor position.
 9→/// Used to drive toolbar button states (pressed/unpressed) in the editor.
10→/// </summary>
11→sealed class FormattingState
12→{
13→  /// <summary>
14→  /// Gets or sets whether bold formatting is active at the cursor.
15→  /// </summary>
16→  public bool IsBold { get; set; }
17→
18→  /// <summary>
19→  /// Gets or sets whether italic formatting is active at the cursor.
20→  /// </summary>
21→  public bool IsItalic { get; set; }
22→
23→  /// <summary>
24→  /// Gets or sets whether underline formatting is active at the cursor.
25→  /// </summary>
26→  public bool IsUnderline { get; set; }
27→
28→  /// <summary>
29→  /// Gets or sets the link URL if the cursor is within a link mark, or null otherwise.
30→  /// </summary>
31→  public string? LinkUrl { get; set; }
32→
33→  /// <summary>
34→  /// Gets whether the cursor is within a link mark.
35→  /// </summary>
36→  public bool HasLink => LinkUrl is not null;
37→
38→  /// <summary>
39→  /// Creates a <see cref="FormattingState"/> from the formatted text at the given cursor position.
40→  /// Finds the span containing the cursor and extracts active marks.
41→  /// </summary>
42→  public static FormattingState FromFormattedText(FormattedText formattedText, int cursorPosition)
43→  {
44→    var state = new FormattingState();
45→
46→    foreach(FormattedSpan span in formattedText.Spans)
47→    {
48→      if(cursorPosition < span.Offset || cursorPosition >= span.Offset + span.Length)
49→      {
50→        continue;
51→      }
52→
53→      foreach(var (name, value) in span.Marks)
54→      {
55→        switch(name)
56→        {
57→          case "bold":
58→            state.IsBold = true;
59→            break;
60→          case "italic":
61→            state.IsItalic = true;
62→            break;
63→          case "underline":
64→            state.IsUnderline = true;
65→            break;
66→          case "link" when value is string url:
67→            state.LinkUrl = url;
68→            break;
69→        }
70→      }
71→
72→      break; // Found the span containing the cursor
73→    }
74→
75→    return state;
76→  }
77→}
