 8→namespace DemoApp.CollaborativeEditor.Controls;
 9→
10→using TextEditFormattedText = Six.Automerge.TextEdit.FormattedText;
11→
12→/// <summary>
13→/// Converts <see cref="TextEditFormattedText"/> spans into Avalonia <see cref="InlineCollection"/>
14→/// on a <see cref="TextBlock"/>. Each <see cref="FormattedSpan"/> becomes a <see cref="Run"/>
15→/// with appropriate font weight, style, and text decorations.
16→/// </summary>
17→static class FormattedTextRenderer
18→{
19→  /// <summary>
20→  /// Renders formatted text onto a TextBlock by replacing its Inlines.
21→  /// </summary>
22→  public static void Render(TextBlock textBlock, TextEditFormattedText formattedText)
23→  {
24→    ArgumentNullException.ThrowIfNull(textBlock);
25→    ArgumentNullException.ThrowIfNull(formattedText);
26→
27→    InlineCollection inlines = textBlock.Inlines ??= [];
28→    inlines.Clear();
29→
30→    foreach(FormattedSpan span in formattedText.Spans)
31→    {
32→      inlines.Add(CreateRun(span));
33→    }
34→  }
35→
36→  /// <summary>
37→  /// Creates an Avalonia <see cref="Run"/> from a <see cref="FormattedSpan"/>,
38→  /// applying bold, italic, and underline marks.
39→  /// </summary>
40→  public static Run CreateRun(FormattedSpan span)
41→  {
42→    ArgumentNullException.ThrowIfNull(span);
43→
44→    var run = new Run(span.Text);
45→    bool hasBold = span.Marks.ContainsKey("bold");
46→    bool hasItalic = span.Marks.ContainsKey("italic");
47→    bool hasUnderline = span.Marks.ContainsKey("underline");
48→
49→    if(hasBold)
50→    {
51→      run.FontWeight = FontWeight.Bold;
52→    }
53→
54→    if(hasItalic)
55→    {
56→      run.FontStyle = FontStyle.Italic;
57→    }
58→
59→    if(hasUnderline)
60→    {
61→      run.TextDecorations = TextDecorations.Underline;
62→    }
63→
64→    return run;
65→  }
66→}
