408→  /// <summary>
409→  /// Throws if this instance has been disposed.
410→  /// </summary>
411→  void ThrowIfDisposed()
412→  {
413→    if(_isDisposed)
414→      throw new ObjectDisposedException(nameof(StorageSubsystem));
415→  }
416→
