311→  // PRIVATE METHODS
312→  // ---------------------------------------------------------------------------------------------------------
313→  void OnAdapterPeerCandidate(object? sender, PeerCandidateEventArgs e)
314→  {
315→    if(sender is not INetworkAdapter adapter) return;
316→
317→    _lock.Wait();
318→    try
319→    {
320→      // Track peer-to-adapter mapping
321→      _peerToAdapter[e.PeerId] = adapter;
322→
323→      // Store peer metadata
324→      if(e.Metadata is not null)
325→      {
326→        _peerMetadata[e.PeerId] = e.Metadata;
327→      }
328→    }
329→    finally
330→    {
331→      _lock.Release();
332→    }
333→
334→    // Forward event to subscribers
335→    PeerCandidate?.Invoke(this, e);
336→  }
337→
338→  void OnAdapterPeerDisconnected(object? sender, PeerDisconnectedEventArgs e)
339→  {
340→    _lock.Wait();
341→    try
342→    {
343→      _peerToAdapter.Remove(e.PeerId);
344→      _peerMetadata.Remove(e.PeerId);
345→    }
346→    finally
347→    {
348→      _lock.Release();
349→    }
350→
351→    // Forward event to subscribers
352→    PeerDisconnected?.Invoke(this, e);
353→  }
354→
355→  void OnAdapterMessageReceived(object? sender, MessageReceivedEventArgs e)
356→  {
357→    var message = e.Message;
358→
359→    // Deduplicate ephemeral messages
360→    if(message is EphemeralMessage ephemeral)
361→    {
362→      if(!ShouldProcessEphemeralMessage(ephemeral))
363→      {
364→        // Already seen this message, skip
365→        return;
366→      }
367→    }
368→
369→    // Forward message to subscribers
370→    MessageReceived?.Invoke(this, e);
371→  }
