373→  /// <summary>
374→  /// Checks if ephemeral message should be processed (deduplication).
375→  /// Returns true if message is new, false if already seen.
376→  /// </summary>
377→  bool ShouldProcessEphemeralMessage(EphemeralMessage message)
378→  {
379→    // Create the unique key: peerId:sessionId:count
380→    var key = $"{message.SenderId}:{message.SessionId}:{message.Count}";
381→
382→    _lock.Wait();
383→    try
384→    {
385→      if(!_seenEphemeralMessages.Add(key))
386→        return false; // Already seen
387→
388→      // Add to seen set
389→      // Cleanup old entries periodically (keep last 1000)
390→      if(_seenEphemeralMessages.Count > 1000)
391→      {
392→        // Remove oldest half
393→        var toRemove = _seenEphemeralMessages.Take(500).ToList();
394→        foreach(var item in toRemove)
395→        {
396→          _seenEphemeralMessages.Remove(item);
397→        }
398→      }
399→
400→      return true; // New message
401→    }
402→    finally
403→    {
404→      _lock.Release();
405→    }
406→  }
407→
408→  void ThrowIfDisposed()
409→  {
410→    if(_isDisposed)
411→    {
412→      throw new ObjectDisposedException(nameof(NetworkSubsystem));
413→    }
414→  }
415→}

