  11→/// <summary>
  12→/// Central repository for managing Automerge documents with persistence and sync.
  13→/// </summary>
  14→/// <remarks>
  15→/// <para>
  16→/// The Repo is the main entry point of this library. To construct a Repo you will need
  17→/// an IStorageAdapter and one or more INetworkAdapters. Once you have a Repo you can
  18→/// use it to obtain DocHandles.
  19→/// </para>
  20→/// <para>
  21→/// This is a C# port of the TypeScript automerge-repo Repo class, maintaining API compatibility.
  22→/// </para>
  23→/// </remarks>
  24→[PublicAPI]
  25→public sealed class Repo : IDisposable
  26→{
  27→  // Subsystems
  28→  readonly StorageSubsystem? _storage;
