 115→  /// <summary>
 116→  /// Initializes a new repository with the specified configuration.
 117→  /// </summary>
 118→  /// <param name="config">Configuration for the repository.</param>
 119→  /// <exception cref="ArgumentNullException">Thrown if config is null.</exception>
 120→  public Repo(RepoConfig config)
 121→  {
 122→    if(config is null)
 123→      throw new ArgumentNullException(nameof(config));
 124→
 125→    // Initialize identity
 126→    _peerId = config.PeerId ?? PeerId.Generate();
 127→    _isEphemeral = config.IsEphemeral;
 128→    _saveDebounceRate = config.SaveDebounceRate;
 129→    _shareConfig = config.ShareConfig ?? ShareConfig.AllowAll;
 130→    _idFactory = config.IdFactory;
 131→    _loggerFactory = config.LoggerFactory ?? NullLoggerFactory.Instance;
 132→    _logger = _loggerFactory.CreateLogger<Repo>();
 133→
 134→    // Initialize storage subsystem
 135→    if(config.Storage is not null)
 136→    {
 137→      _storage = new StorageSubsystem(config.Storage);
 138→      _storage.DocumentLoaded += OnStorageDocumentLoaded;
 139→      _storage.DocumentSaved += OnStorageDocumentSaved;
 140→    }
 141→
 142→    // Initialize network subsystem
 143→    _network = new NetworkSubsystem(config.NetworkAdapters);
 144→    _network.PeerCandidate += OnNetworkPeerCandidate;
 145→    _network.PeerDisconnected += OnNetworkPeerDisconnected;
 146→    _network.MessageReceived += OnNetworkMessageReceived;
 147→
 148→    // Initialize synchronizer
 149→    _synchronizer = new CollectionSynchronizer(
 150→      GetDocument,
 151→      UpdateDocumentAsync,
 152→      GetPeerMetadata,
 153→      RequestDocument,
 154→      GetDocumentLock,
 155→      config.SyncDebounceRate,
 156→      config.Denylist,
 157→      config.LoggerFactory);
 158→
 159→    _synchronizer.MessageToSend += OnSynchronizerMessage;
 160→    _synchronizer.SyncStateChanged += OnSynchronizerSyncStateChanged;
 161→    _synchronizer.DocumentUnavailable += OnSynchronizerDocumentUnavailable;
 162→
 163→    // Set share and access policies
 164→    if(_shareConfig.Announce is not null)
 165→    {
 166→      _synchronizer.SetSharePolicy(AdaptAnnouncePolicy);
 167→    }
 168→
 169→    if(_shareConfig.Access is not null)
 170→    {
 171→      _synchronizer.SetAccessPolicy(AdaptAccessPolicy);
 172→    }
 173→  }
