 350→    }
 351→
 352→    // Validate document ID
 353→    if(!DocumentId.IsValid(documentId))
 354→    {
 355→      throw new ArgumentException($"Invalid document ID: {documentId}");
 356→    }
 357→
 358→    DocHandle<T> handle;
 359→
 360→    await _handleLock.WaitAsync().ConfigureAwait(false);
 361→    try
 362→    {
 363→      // Check if already exists
 364→      if(_handleCache.ContainsKey(documentId))
 365→      {
 366→        throw new InvalidOperationException($"Document already exists: {documentId}");
 367→      }
 368→
 369→      // Create document
 370→      var doc = AutomergeDocument.Create();
 371→
 372→      // Create handle
 373→      handle = new DocHandle<T>(
 374→        documentId,
 375→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 376→        doc,
 377→        CreateDocHandleLogger<T>());
 378→
 379→      // Cache handle
 380→      _handleCache[documentId] = handle;
 381→    }
 382→    finally
 383→    {
 384→      _handleLock.Release();
 385→    }
 386→
 387→    // Register outside the lock to prevent deadlocks
 388→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 389→
 390→    // Emit event
 391→    DocumentLoaded?.Invoke(this,
 392→      new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 393→
 394→    return handle;
 395→  }
