 680→  /// <summary>
 681→  /// Creates a new document as a clone of an existing document.
 682→  /// </summary>
 683→  /// <typeparam name="T">The document content type.</typeparam>
 684→  /// <param name="source">The source handle to clone.</param>
 685→  /// <returns>A task that resolves to a handle to the cloned document.</returns>
 686→  public async Task<DocHandle<T>> Clone<T>(DocHandle<T> source)
 687→  {
 688→    if(source is null)
 689→      throw new ArgumentNullException(nameof(source));
 690→
 691→    ThrowIfDisposed();
 692→
 693→    // Generate new document ID
 694→    var newDocumentId = _idFactory is not null
 695→      ? DocumentId.FromBinary(await _idFactory(Array.Empty<string>()).ConfigureAwait(false))
 696→      : DocumentId.Generate();
 697→
 698→    // Clone the underlying document
 699→    var sourceDocHandle = source;
 700→    var sourceDoc = sourceDocHandle.Doc();
 701→    var clonedDocBytes = (sourceDoc as AutomergeDocument)!.Save();
 702→    var clonedDoc = AutomergeDocument.Load(clonedDocBytes);
 703→
 704→    // Create new handle
 705→    var handle = new DocHandle<T>(
 706→      newDocumentId,
 707→      new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 708→      clonedDoc,
 709→      CreateDocHandleLogger<T>());
 710→
 711→    await _handleLock.WaitAsync().ConfigureAwait(false);
 712→    try
 713→    {
 714→      _handleCache[newDocumentId] = handle;
 715→    }
 716→    finally
 717→    {
 718→      _handleLock.Release();
 719→    }
 720→
 721→    // Register outside the lock to prevent deadlocks
 722→    await RegisterHandle(newDocumentId, handle).ConfigureAwait(false);
 723→
 724→    // Emit event
 725→    DocumentLoaded?.Invoke(this,
 726→      new DocumentEventArgs { DocumentId = newDocumentId, Handle = handle });
 727→
 728→    return handle;
 729→  }
