 773→  /// <summary>
 774→  /// Imports a document from binary data.
 775→  /// </summary>
 776→  /// <typeparam name="T">The document content type.</typeparam>
 777→  /// <param name="data">The binary data to import.</param>
 778→  /// <param name="documentId">Optional document ID. If null, a new ID is generated.</param>
 779→  /// <returns>A task that resolves to a handle to the imported document.</returns>
 780→  public async Task<DocHandle<T>> Import<T>(byte[] data, string? documentId = null)
 781→  {
 782→    if(data is null || data.Length == 0)
 783→      throw new ArgumentException("Data cannot be null or empty", nameof(data));
 784→
 785→    ThrowIfDisposed();
 786→
 787→    // Load document from binary
 788→    var doc = AutomergeDocument.Load(data);
 789→
 790→    // Generate or validate document ID
 791→    if(documentId is null)
 792→    {
 793→      // Extract ID from document heads
 794→      var heads = doc.GetHeads();
 795→      documentId = _idFactory is not null
 796→        ? DocumentId.FromBinary(await _idFactory(heads).ConfigureAwait(false))
 797→        : DocumentId.Generate();
 798→    }
 799→    else if(!DocumentId.IsValid(documentId))
 800→    {
 801→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 802→    }
 803→
 804→    // Create handle
 805→    var handle = new DocHandle<T>(
 806→      documentId,
 807→      new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>() },
 808→      doc,
 809→      CreateDocHandleLogger<T>());
 810→
 811→    await _handleLock.WaitAsync().ConfigureAwait(false);
 812→    try
 813→    {
 814→      // Check if already exists
 815→      if(_handleCache.ContainsKey(documentId))
 816→      {
 817→        throw new InvalidOperationException($"Document already exists: {documentId}");
 818→      }
 819→
 820→      _handleCache[documentId] = handle;
 821→    }
 822→    finally
 823→    {
 824→      _handleLock.Release();
 825→    }
 826→
 827→    // Register outside the lock to prevent deadlocks
 828→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 829→
 830→    // Emit event
 831→    DocumentLoaded?.Invoke(this,
 832→      new DocumentEventArgs { DocumentId = DocumentId.Parse(documentId), Handle = handle });
 833→
 834→    return handle;
 835→  }
