1121→  /// <summary>
1122→  /// Async callback for synchronizer to update document.
1123→  /// </summary>
1124→  async Task UpdateDocumentAsync(string documentId, AutomergeDocument document)
1125→  {
1126→    await _handleLock.WaitAsync().ConfigureAwait(false);
1127→    IDocHandle? handle;
1128→    bool isNewHandle = false;
1129→    try
1130→    {
1131→      if(!_handleCache.TryGetValue(documentId, out handle))
1132→      {
1133→        // Document received from sync but no handle exists yet.
1134→        // This happens when a peer sends sync data for a document the server hasn't seen.
1135→        // RequestDocument runs Find() in Task.Run (async), so the handle may not be cached yet.
1136→        // Create a handle now to prevent the synced data from being silently discarded.
1137→        var newHandle = new DocHandle<object>(
1138→          documentId,
1139→          new DocHandleOptions<object>
1140→          {
1141→            IsNew = false,
1142→            ViewFactory = CreateViewFactory<object>()
1143→          },
1144→          document: null,
1145→          logger: CreateDocHandleLogger<object>());
1146→
1147→        _handleCache[documentId] = newHandle;
1148→        handle = newHandle;
1149→        isNewHandle = true;
1150→      }
1151→    }
1152→    finally
1153→    {
1154→      _handleLock.Release();
1155→    }
1156→
1157→    if(isNewHandle)
1158→    {
1159→      // New handle discovered via sync — initialize lifecycle: Idle → Loading → Ready
1160→      handle.Begin();
1161→      handle.Initialize(document, isNewDocument: false);
1162→      handle.DoneLoading();
1163→
1164→      // Wire up events for persistence and synchronizer notifications.
1165→      // RegisterHandle is async; fire-and-forget since this callback is synchronous.
1166→      _ = Task.Run(async () =>
1167→      {
1168→        try
1169→        {
1170→          await RegisterHandle(documentId, (DocHandle<object>)handle).ConfigureAwait(false);
1171→
1172→          DocumentLoaded?.Invoke(this, new DocumentEventArgs
1173→          {
1174→            DocumentId = DocumentId.Parse(documentId),
1175→            Handle = handle
1176→          });
1177→        }
1178→        catch(Exception ex)
1179→        {
1180→          _logger.LogError(ex, "UpdateDocument: sync-discovered handle registration failed [DocumentId={DocumentId}]", documentId);
1181→        }
1182→      });
1183→    }
1184→    else if(handle.State == HandleState.Requesting || handle.State == HandleState.Loading)
1185→    {
1186→      // Handle exists but waiting for data — initialize with received document
1187→      handle.Initialize(document, isNewDocument: false);
1188→      handle.DoneLoading();  // Transition to Ready
1189→    }
1190→    else if(handle.State == HandleState.Ready)
1191→    {
1192→      // Handle already initialized — notify about remote change (triggers HeadsChanged → save)
1193→      await handle.NotifyRemoteChangeAsync(document).ConfigureAwait(false);
1194→    }
1195→  }
