1246→  #region Persistence and Cleanup
1247→
1248→  /// <summary>
1249→  /// Flushes pending saves for specified documents (or all documents).
1250→  /// </summary>
1251→  /// <param name="documentIds">Optional list of document IDs to flush. If null, flushes all.</param>
1252→  public async Task Flush(IEnumerable<string>? documentIds = null)
1253→  {
1254→    if(_storage is null) return;
1255→
1256→    ThrowIfDisposed();
1257→
1258→    var idsToFlush = documentIds?.ToList() ?? _handleCache.Keys.ToList();
1259→
1260→    var saveTasks = new List<Task>();
1261→
1262→    foreach(var documentId in idsToFlush)
1263→    {
1264→      // Cancel pending throttled save
1265→      await _saveLock.WaitAsync().ConfigureAwait(false);
1266→      try
1267→      {
1268→        if(_pendingSaves.TryGetValue(documentId, out var cts))
1269→        {
1270→          cts.Cancel();
1271→          _pendingSaves.Remove(documentId);
1272→        }
1273→      }
1274→      finally
1275→      {
1276→        _saveLock.Release();
1277→      }
1278→
1279→      // Perform immediate save
1280→      saveTasks.Add(PerformSave(documentId));
1281→    }
1282→
1283→    await Task.WhenAll(saveTasks).ConfigureAwait(false);
1284→  }
