1286→  /// <summary>
1287→  /// Removes a document from the cache without deleting from storage.
1288→  /// Useful for memory management.
1289→  /// </summary>
1290→  /// <param name="documentId">The document ID to remove from cache.</param>
1291→  public async Task RemoveFromCache(string documentId)
1292→  {
1293→    if(string.IsNullOrWhiteSpace(documentId))
1294→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
1295→
1296→    ThrowIfDisposed();
1297→
1298→    // Flush first
1299→    await Flush(new[] { documentId }).ConfigureAwait(false);
1300→
1301→    await _handleLock.WaitAsync().ConfigureAwait(false);
1302→    IDocHandle? handle;
1303→    try
1304→    {
1305→      if(!_handleCache.TryGetValue(documentId, out handle))
1306→      {
1307→        return;
1308→      }
1309→
1310→      _handleCache.Remove(documentId);
1311→    }
1312→    finally
1313→    {
1314→      _handleLock.Release();
1315→    }
1316→
1317→    // Unregister from synchronizer
1318→    await _synchronizer.RemoveDocument(documentId).ConfigureAwait(false);
1319→
1320→    // Unload handle
1321→    handle.Unload();
1322→  }
