292→  sealed class StaticOptionsMonitor(SignalRConnectionServiceOptions options)
293→    : IOptionsMonitor<SignalRConnectionServiceOptions>
294→  {
295→    public SignalRConnectionServiceOptions CurrentValue => options;
296→
297→    public SignalRConnectionServiceOptions Get(string? name) => options;
298→
299→    public IDisposable? OnChange(Action<SignalRConnectionServiceOptions, string?> listener) => null;
300→  }
301→}
