  4→namespace Six.Automerge.Repository.Storage.FileSystem;
  5→
  6→/// <summary>
  7→/// File system storage adapter that persists data to local disk with in-memory caching.
  8→/// </summary>
  9→/// <remarks>
 10→/// <para>
 11→/// This adapter stores data in a hierarchical directory structure with sharding to prevent
 12→/// directory overflow. The first key component is split: first 2 chars become a directory,
 13→/// remaining chars become a subdirectory.
 14→/// </para>
 15→/// <para>
 16→/// Example: Key ["abc123", "snapshot", "hash"] → baseDir/ab/c123/snapshot/hash
 17→/// </para>
 18→/// <para>
 19→/// Data is cached in memory using MemoryCache for fast repeated reads.
 20→/// </para>
 21→/// </remarks>
 22→[PublicAPI]
 23→public sealed class FileSystemStorageAdapter : StorageAdapterBase, IDisposable
 24→{
 25→  readonly string _baseDirectory;
 26→  readonly IMemoryCache _cache;
 27→  readonly HashSet<string> _cacheKeys = [];
 28→  readonly SemaphoreSlim _lock = new(1, 1);
 29→  readonly TimeSpan _cacheSlidingExpiration;
 30→  bool _disposed;
 31→
 32→
 33→  /// <summary>
 34→  /// Creates a new file system storage adapter.
 35→  /// </summary>
 36→  /// <param name="baseDirectory">Base directory for storage. Created if it doesn't exist.</param>
 37→  /// <param name="options">Optional configuration. If null, uses default settings.</param>
 38→  public FileSystemStorageAdapter(string baseDirectory, FileSystemStorageOptions? options = null)
 39→  {
 40→    if(string.IsNullOrWhiteSpace(baseDirectory))
 41→      throw new ArgumentException("Base directory cannot be null or whitespace", nameof(baseDirectory));
 42→
 43→    options ??= new FileSystemStorageOptions();
 44→
 45→    _baseDirectory = Path.GetFullPath(baseDirectory);
 46→    _cacheSlidingExpiration = options.CacheSlidingExpiration;
 47→
 48→    // Initialize cache with size limit
 49→    _cache = new MemoryCache(new MemoryCacheOptions
 50→    {
 51→      SizeLimit = options.CacheSizeLimit
 52→    });
 53→
 54→    // Create base directory if it doesn't exist
 55→    Directory.CreateDirectory(_baseDirectory);
 56→  }
 57→
 58→
 59→  /// <summary>
 60→  /// Loads data for a storage key. Checks cache first, then disk.
 61→  /// </summary>
 62→  public override async Task<byte[]?> Load(StorageKey key)
 63→  {
 64→    ThrowIfDisposed();
 65→
 66→    await _lock.WaitAsync();
 67→    try
 68→    {
 69→      return await LoadCore(key);
 70→    }
 71→    finally
 72→    {
 73→      _lock.Release();
 74→    }
 75→  }
 76→
 77→
 78→  /// <summary>
 79→  /// Loads data for a storage key without acquiring the lock.
 80→  /// Checks cache first, then reads from disk and populates cache.
 81→  /// </summary>
 82→  /// <remarks>
 83→  /// Callers must hold <see cref="_lock"/> before calling this method.
 84→  /// This exists so <see cref="LoadRange"/> can call it from within its own lock scope
 85→  /// without causing a deadlock.
 86→  /// </remarks>
 87→  async Task<byte[]?> LoadCore(StorageKey key)
 88→  {
 89→    var cacheKey = GetCacheKey(key);
 90→
 91→    // Try cache first
 92→    if(_cache.TryGetValue(cacheKey, out byte[]? cachedData))
 93→    {
 94→      return cachedData;
 95→    }
 96→
 97→    // Load from disk
 98→    var filePath = GetFilePath(key);
 99→
100→    try
101→    {
102→      if(!File.Exists(filePath))
103→        return null;
104→
105→      var data = await File.ReadAllBytesAsync(filePath);
106→
107→      // Store in cache with sliding expiration
108→      var cacheOptions = new MemoryCacheEntryOptions()
109→        .SetSize(data.Length)
110→        .SetSlidingExpiration(_cacheSlidingExpiration);
111→
112→      _cache.Set(cacheKey, data, cacheOptions);
113→
114→      // Track cache key for prefix-based eviction
115→      _cacheKeys.Add(cacheKey);
116→
117→      return data;
118→    }
119→    catch(FileNotFoundException)
120→    {
121→      return null;
122→    }
123→    catch(DirectoryNotFoundException)
124→    {
125→      return null;
126→    }
127→  }
128→
129→  /// <summary>
130→  /// Saves data to storage. Updates cache and writes to disk.
131→  /// </summary>
132→  public override async Task Save(StorageKey key, byte[] data)
133→  {
134→    ThrowIfDisposed();
135→
136→    if(data == null)
137→      throw new ArgumentNullException(nameof(data));
138→
139→    var cacheKey = GetCacheKey(key);
140→    var filePath = GetFilePath(key);
141→
142→    await _lock.WaitAsync();
143→    try
144→    {
145→      // Create directory structure
146→      var directory = Path.GetDirectoryName(filePath);
147→      if(!string.IsNullOrEmpty(directory))
148→      {
149→        Directory.CreateDirectory(directory);
150→      }
151→
152→      // Write to disk
153→      await File.WriteAllBytesAsync(filePath, data);
154→
155→      // Update cache
156→      var cacheOptions = new MemoryCacheEntryOptions()
157→        .SetSize(data.Length)
158→        .SetSlidingExpiration(_cacheSlidingExpiration);
159→
160→      _cache.Set(cacheKey, data, cacheOptions);
161→
162→      // Track cache key for prefix-based eviction
163→      _cacheKeys.Add(cacheKey);
164→    }
165→    finally
166→    {
167→      _lock.Release();
168→    }
169→  }
170→
171→  /// <summary>
172→  /// Removes data for a storage key. Removes from cache and deletes file.
173→  /// </summary>
174→  public override async Task Remove(StorageKey key)
175→  {
176→    ThrowIfDisposed();
177→
178→    var cacheKey = GetCacheKey(key);
179→    var filePath = GetFilePath(key);
180→
181→    await _lock.WaitAsync();
182→    try
183→    {
184→      // Remove from cache and tracking set
185→      _cache.Remove(cacheKey);
186→      _cacheKeys.Remove(cacheKey);
187→
188→      // Delete file (ignore if doesn't exist)
189→      if(File.Exists(filePath))
190→      {
191→        File.Delete(filePath);
192→      }
193→    }
194→    finally
195→    {
196→      _lock.Release();
197→    }
198→  }
199→
200→  /// <summary>
201→  /// Loads all chunks matching a key prefix. Combines cached and disk data.
202→  /// </summary>
203→  public override async Task<IReadOnlyList<Chunk>> LoadRange(StorageKey keyPrefix)
204→  {
205→    ThrowIfDisposed();
206→
207→    var dirPath = GetFilePath(keyPrefix);
208→    var results = new Dictionary<string, Chunk>(); // Use dict to deduplicate
209→
210→    await _lock.WaitAsync();
211→    try
212→    {
213→      // Walk directory tree to find all files
214→      var diskFiles = await WalkDirectory(dirPath);
215→
216→      // Load each file (will hit cache if available)
217→      foreach(var filePath in diskFiles)
218→      {
219→        // Convert file path back to StorageKey
220→        var relativePath = Path.GetRelativePath(_baseDirectory, filePath);
221→        var components = ParseFilePathToKey(relativePath);
222→        var storageKey = new StorageKey(components);
223→
224→        // Check if key matches prefix
225→        if(storageKey.StartsWith(keyPrefix))
226→        {
227→          // Load data without re-acquiring lock (hits cache if present)
228→          var data = await LoadCore(storageKey);
229→          if(data != null)
230→          {
231→            var keyString = storageKey.ToDebugString();
232→            results[keyString] = new Chunk(storageKey, data);
233→          }
234→        }
235→      }
236→
237→      return results.Values.ToList();
238→    }
239→    finally
240→    {
241→      _lock.Release();
242→    }
243→  }
244→
245→  /// <summary>
246→  /// Removes all keys matching a prefix. Deletes directory tree and clears from cache.
247→  /// </summary>
248→  public override async Task RemoveRange(StorageKey keyPrefix)
249→  {
250→    ThrowIfDisposed();
251→
252→    var dirPath = GetFilePath(keyPrefix);
253→
254→    await _lock.WaitAsync();
255→    try
256→    {
257→      // Delete directory tree from disk
258→      if(Directory.Exists(dirPath))
259→      {
260→        Directory.Delete(dirPath, recursive: true);
261→      }
262→
263→      // Evict all cache entries matching the prefix
264→      var prefixString = keyPrefix.ToDebugString();
265→      var keysToRemove = _cacheKeys.Where(k => k.StartsWith(prefixString, StringComparison.Ordinal)).ToList();
266→      foreach(var cacheKey in keysToRemove)
267→      {
268→        _cache.Remove(cacheKey);
269→        _cacheKeys.Remove(cacheKey);
270→      }
271→    }
272→    catch(DirectoryNotFoundException)
273→    {
274→      // Directory already deleted, ignore
275→    }
276→    finally
277→    {
278→      _lock.Release();
279→    }
280→  }
281→
282→  /// <summary>
283→  /// Gets metadata about all chunks matching a key prefix without loading the full data.
284→  /// This is more efficient than the base implementation as it only reads file metadata.
285→  /// </summary>
286→  public override async Task<IReadOnlyList<ChunkInfo>> GetChunkInfo(StorageKey keyPrefix)
287→  {
288→    ThrowIfDisposed();
289→
290→    var dirPath = GetFilePath(keyPrefix);
291→    var results = new List<ChunkInfo>();
292→
293→    await _lock.WaitAsync();
294→    try
295→    {
296→      // Walk directory tree to find all files
297→      var diskFiles = await WalkDirectory(dirPath);
298→
299→      // Get metadata for each file
300→      foreach(var filePath in diskFiles)
301→      {
302→        // Convert file path back to StorageKey
303→        var relativePath = Path.GetRelativePath(_baseDirectory, filePath);
304→        var components = ParseFilePathToKey(relativePath);
305→        var storageKey = new StorageKey(components);
306→
307→        // Check if key matches prefix
308→        if(storageKey.StartsWith(keyPrefix))
309→        {
310→          // Get file size without loading data
311→          var fileInfo = new FileInfo(filePath);
312→          if(fileInfo.Exists)
313→          {
314→            results.Add(new ChunkInfo(storageKey, (int)fileInfo.Length));
315→          }
316→        }
317→      }
318→
319→      return results;
320→    }
321→    finally
322→    {
323→      _lock.Release();
324→    }
325→  }
