195→  async Task HandleJoinAsync(EditorViewModel vm, string documentId)
196→  {
197→    if(vm.RepoService is null)
198→    {
199→      _logger.LogWarning("Cannot join document {DocumentId}: no server connection", documentId);
200→      await Dispatcher.UIThread.InvokeAsync(() =>
