203→  /// <summary>
204→  /// Opens a TextDocument on a remote repo with retry logic.
205→  /// The sync protocol may deliver the empty document shell before the "text" field
206→  /// change arrives, so OpenAsync can initially return null. This helper retries.
207→  /// </summary>
208→  static async Task<TextDocument?> OpenWithRetryAsync(
209→    Repo repo, string documentId, TimeSpan? totalTimeout = null)
210→  {
211→    totalTimeout ??= TimeSpan.FromSeconds(5);
212→    var deadline = DateTime.UtcNow + totalTimeout.Value;
213→
214→    while(DateTime.UtcNow < deadline)
215→    {
216→      TextDocument? doc = await TextDocument.OpenAsync(
217→        repo, documentId, timeout: TimeSpan.FromMilliseconds(500));
218→
219→      if(doc is not null)
220→      {
221→        return doc;
222→      }
223→
224→      await Task.Delay(100);
225→    }
226→
227→    return null;
228→  }
229→
230→  static async Task WaitUntilAsync(Func<bool> condition, TimeSpan timeout)
231→  {
232→    var deadline = DateTime.UtcNow + timeout;
233→    while(!condition() && DateTime.UtcNow < deadline)
234→    {
235→      await Task.Delay(50);
236→    }
237→
238→    condition().Should().BeTrue("condition should be met within timeout");
239→  }
240→}
