11→/// <summary>
12→/// A reusable status bar showing connection state, peer info, document ID, and server URL.
13→/// </summary>
14→[PublicAPI]
15→public partial class ConnectionStatusBar : UserControl
16→{
17→  public ConnectionStatusBar()
18→  {
19→    InitializeComponent();
20→  }
21→
22→  /// <inheritdoc />
23→  protected override void OnDataContextChanged(EventArgs e)
24→  {
25→    base.OnDataContextChanged(e);
26→
27→    if(DataContext is ConnectionStatusBarViewModel vm)
28→    {
29→      vm.PropertyChanged += OnViewModelPropertyChanged;
30→      UpdateConnectionDot(vm.ConnectionState);
31→    }
32→  }
33→
34→  void OnViewModelPropertyChanged(object? sender, System.ComponentModel.PropertyChangedEventArgs e)
35→  {
36→    if(e.PropertyName == nameof(ConnectionStatusBarViewModel.ConnectionState)
37→       && sender is ConnectionStatusBarViewModel vm)
38→    {
39→      UpdateConnectionDot(vm.ConnectionState);
40→    }
41→  }
42→
43→  void UpdateConnectionDot(ConnectionState state)
44→  {
45→    Ellipse? dot = this.FindControl<Ellipse>("ConnectionDot");
46→    if(dot is null)
47→    {
48→      return;
49→    }
50→
51→    dot.Fill = state switch
52→    {
53→      ConnectionState.Connected => new SolidColorBrush(Color.Parse("#00CC00")),
54→      ConnectionState.Connecting => new SolidColorBrush(Color.Parse("#FFAA00")),
55→      ConnectionState.Reconnecting => new SolidColorBrush(Color.Parse("#FFAA00")),
56→      _ => new SolidColorBrush(Color.Parse("#CC0000"))
57→    };
58→  }
59→
60→  async void OnCopyDocumentId(object? sender, RoutedEventArgs e)
61→  {
62→    if(DataContext is not ConnectionStatusBarViewModel vm || string.IsNullOrEmpty(vm.DocumentId))
63→    {
64→      return;
65→    }
66→
67→    IClipboard? clipboard = TopLevel.GetTopLevel(this)?.Clipboard;
68→    if(clipboard is not null)
69→    {
70→      await clipboard.SetTextAsync(vm.DocumentId);
71→    }
72→  }
73→}
