471→static long GetTotalViews(AutomergeDocument doc)
472→{
473→    var json = doc.HydrateJson();
474→    using var parsed = JsonDocument.Parse(json);
475→    if (parsed.RootElement.TryGetProperty("total_views", out var views))
476→    {
477→        if (views.ValueKind == JsonValueKind.Number)
478→        {
479→            return views.GetInt64();
480→        }
481→    }
482→
483→    return 0;
484→}
