using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.Documents;
using Avalonia.Media;

namespace DemoApp.CollaborativeEditor.Controls;

using TextEditFormattedText = Six.Automerge.TextEdit.FormattedText;

public partial class RichTextEditor : UserControl
{
  public static readonly StyledProperty<string> TextProperty =
    AvaloniaProperty.Register<RichTextEditor, string>(nameof(Text), defaultValue: string.Empty);

  public static readonly StyledProperty<TextEditFormattedText?> FormattedTextProperty =
    AvaloniaProperty.Register<RichTextEditor, TextEditFormattedText?>(nameof(FormattedText));

  public static readonly StyledProperty<int> CaretIndexProperty =
    AvaloniaProperty.Register<RichTextEditor, int>(nameof(CaretIndex));

  public static readonly StyledProperty<int> SelectionStartProperty =
    AvaloniaProperty.Register<RichTextEditor, int>(nameof(SelectionStart));

  public static readonly StyledProperty<int> SelectionEndProperty =
    AvaloniaProperty.Register<RichTextEditor, int>(nameof(SelectionEnd));

  bool _isSyncingText;

  public RichTextEditor()
  {
    InitializeComponent();
    WireInputTextBox();
  }

  public string Text
  {
    get => GetValue(TextProperty);
    set => SetValue(TextProperty, value);
  }

  public TextEditFormattedText? FormattedText
  {
    get => GetValue(FormattedTextProperty);
    set => SetValue(FormattedTextProperty, value);
  }

  public int CaretIndex
  {
    get => GetValue(CaretIndexProperty);
    set => SetValue(CaretIndexProperty, value);
  }

  public int SelectionStart
  {
    get => GetValue(SelectionStartProperty);
    set => SetValue(SelectionStartProperty, value);
  }

  public int SelectionEnd
  {
    get => GetValue(SelectionEndProperty);
    set => SetValue(SelectionEndProperty, value);
  }

  /// <summary>
  /// Gets whether the internal text input has keyboard focus.
  /// </summary>
  public bool IsEditorFocused => InputTextBox.IsFocused;

  protected override void OnPropertyChanged(AvaloniaPropertyChangedEventArgs change)
  {
    base.OnPropertyChanged(change);

    if(change.Property == TextProperty)
    {
      SyncTextToInputTextBox();
    }
    else if(change.Property == FormattedTextProperty)
    {
      RenderFormattedText();
    }
  }

  void WireInputTextBox()
  {
    InputTextBox.PropertyChanged += (_, args) =>
    {
      if(args.Property == TextBox.TextProperty && !_isSyncingText)
      {
        _isSyncingText = true;
        try
        {
          Text = InputTextBox.Text ?? string.Empty;
        }
        finally
        {
          _isSyncingText = false;
        }
      }
      else if(args.Property == TextBox.CaretIndexProperty)
      {
        CaretIndex = InputTextBox.CaretIndex;
      }
      else if(args.Property == TextBox.SelectionStartProperty)
      {
        SelectionStart = InputTextBox.SelectionStart;
      }
      else if(args.Property == TextBox.SelectionEndProperty)
      {
        SelectionEnd = InputTextBox.SelectionEnd;
      }
    };
  }

  void SyncTextToInputTextBox()
  {
    if(_isSyncingText)
    {
      return;
    }

    _isSyncingText = true;
    try
    {
      string newText = Text ?? string.Empty;
      if(InputTextBox.Text != newText)
      {
        int caretBefore = InputTextBox.CaretIndex;
        InputTextBox.Text = newText;

        // Restore caret position, clamped to text length
        InputTextBox.CaretIndex = Math.Min(caretBefore, newText.Length);
      }
    }
    finally
    {
      _isSyncingText = false;
    }
  }

  void RenderFormattedText()
  {
    TextEditFormattedText? formatted = FormattedText;
    Console.Error.WriteLine($"[RichTextEditor] RenderFormattedText called, formatted={formatted is not null}, spans={formatted?.Spans.Count ?? 0}");
    if(formatted is null)
    {
      DisplayTextBlock.Inlines?.Clear();
      return;
    }

    FormattedTextRenderer.Render(DisplayTextBlock, formatted);
    Console.Error.WriteLine($"[RichTextEditor] After render, inlines count={DisplayTextBlock.Inlines?.Count ?? 0}");
  }
}

