 21→/// This is a C# port of the TypeScript automerge-repo Repo class, maintaining API compatibility.
 22→/// </para>
 23→/// </remarks>
 24→[PublicAPI]
 25→public sealed class Repo : IDisposable
 26→{
 27→  // Subsystems
 28→  readonly StorageSubsystem? _storage;
 29→  readonly NetworkSubsystem _network;
 30→  readonly CollectionSynchronizer _synchronizer;
 31→
 32→  // Configuration
 33→  readonly PeerId _peerId;
 34→  readonly bool _isEphemeral;
 35→  readonly int _saveDebounceRate;
 36→  readonly ShareConfig _shareConfig;
 37→  readonly Func<IReadOnlyList<string>, Task<byte[]>>? _idFactory;
 38→  readonly ILoggerFactory _loggerFactory;
 39→  readonly ILogger<Repo> _logger;
 40→
 41→  // Handle management
 42→  readonly Dictionary<string, IDocHandle> _handleCache = [];
 43→  readonly Dictionary<string, Task<IDocHandle>> _findInProgress = [];
 44→  readonly Dictionary<string, SemaphoreSlim> _documentLockFallbacks = [];
 45→  readonly SemaphoreSlim _handleLock = new(1, 1);
 46→
 47→  // Save throttling
 48→  readonly Dictionary<string, CancellationTokenSource> _pendingSaves = [];
