 55→
 56→  /// <summary>
 57→  /// Raised when a document is loaded and ready.
 58→  /// </summary>
 59→  public event EventHandler<DocumentEventArgs>? DocumentLoaded;
 60→
 61→  /// <summary>
 62→  /// Raised when a document is deleted.
 63→  /// </summary>
 64→  public event EventHandler<DocumentDeletedEventArgs>? DocumentDeleted;
 65→
 66→  /// <summary>
 67→  /// Raised when a document is unavailable from all peers.
 68→  /// </summary>
 69→  public event EventHandler<DocumentUnavailableEventArgs>? DocumentUnavailable;
 70→
 71→  /// <summary>
 72→  /// Raised when a peer connects.
 73→  /// </summary>
 74→  public event EventHandler<PeerEventArgs>? PeerConnected;
 75→
 76→  /// <summary>
 77→  /// Raised when a peer disconnects.
 78→  /// </summary>
 79→  public event EventHandler<PeerEventArgs>? PeerDisconnected;
 80→
 81→  #endregion
 82→
 83→  #region Properties
 84→
 85→  /// <summary>
