using Aspire.Hosting;

var builder = DistributedApplication.CreateBuilder(args);

// RESOURCES
// -------------------------------------------------------------------------------


// PROJECTS (APPS)
// -------------------------------------------------------------------------------

// Backend for collaborative apps
var api = builder.AddProject<Projects.Server_Api>("api")
  .WithExternalHttpEndpoints()
  .WithReplicas(1);


// DEMO APPS
// -------------------------------------------------------------------------------

// Collaborative Editor — rich text CRDT demo
builder.AddProject<Projects.DemoApp_CollaborativeEditor>("collaborative-editor")
  .WithReference(api)
  .WaitFor(api)
  //.WithExplicitStart()
  .WithReplicas(4)
  .ExcludeFromManifest();

// Figma Clone — collaborative canvas demo
builder.AddProject<Projects.DemoApp_CollaborativeDrawing>("collaborative-drawing")
  .WithReference(api)
  .WaitFor(api)
  .WithExplicitStart()
  .WithReplicas(2)
  .ExcludeFromManifest();

// Task Board — collaborative kanban board demo
builder.AddProject<Projects.DemoApp_CollaborativeTaskBoard>("collaborative-task-board")
  .WithReference(api)
  .WaitFor(api)
  .WithExplicitStart()
  .WithReplicas(2)
  .ExcludeFromManifest();

builder.Build().Run();
